import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.BXzK3EA4.js";const i="/assets/image%20(1)%20(1)%20(1)%20(1)%20(1)%20(1)%20(1)%20(1)%20(1)%20(1)%20(1)%20(1)%20(1).BsrjVyNN.png",n="/assets/image%20(1)%20(1)%20(1)%20(1)%20(1)%20(1)%20(1)%20(1)%20(1)%20(1)%20(1)%20(1)%20(1)%20(1).BcDpUupU.png",s="/assets/image%20(2)%20(1)%20(1)%20(1)%20(1)%20(1)%20(1).BNZsgKKk.png",c="/assets/image%20(107).DFASIVmq.png",b=JSON.parse('{"title":"Pocketful","description":"","frontmatter":{},"headers":[],"relativePath":"connect-brokers/brokers/pocketful.md","filePath":"connect-brokers/brokers/pocketful.md"}'),l={name:"connect-brokers/brokers/pocketful.md"};function p(d,e,u,h,g,f){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="pocketful" tabindex="-1">Pocketful <a class="header-anchor" href="#pocketful" aria-label="Permalink to &quot;Pocketful&quot;">​</a></h1><hr><h3 id="pocketful-1" tabindex="-1">Pocketful <a class="header-anchor" href="#pocketful-1" aria-label="Permalink to &quot;Pocketful&quot;">​</a></h3><p>Pocketful is a SEBI-registered Indian stock broker offering a modern trading platform with support for multiple asset classes and a powerful API suite. With a focus on automation, speed, and flexibility, Pocketful provides developers and trading system builders direct access to its brokerage services through the <a href="https://api.pocketful.in/" target="_blank" rel="noreferrer">developer portal</a>.</p><p>For Tradeboard integration, Pocketful enables algorithmic trading with secure API authentication, real-time data streaming, and efficient order placement across equities and derivatives.</p><hr><h4 id="app-registration-and-api-credentials" tabindex="-1">App Registration and API Credentials <a class="header-anchor" href="#app-registration-and-api-credentials" aria-label="Permalink to &quot;App Registration and API Credentials&quot;">​</a></h4><p>The integration begins with creating an app via the Pocketful Developer Portal. This app generates the required credentials for secure API access.</p><hr><p><strong>Step-by-Step Guide to Registering Your App</strong></p><p><strong>Step 1: Visit the Developer Portal</strong><br> Go to <a href="https://api.pocketful.in/" target="_blank" rel="noreferrer">https://api.pocketful.in</a> and log in with your registered email ID or client ID.</p><figure><img src="'+i+'" alt=""><figcaption></figcaption></figure><p><strong>Step 2: Navigate to &#39;Apps&#39; and Create a New App</strong><br> Click on “+ Create App”.</p><figure><img src="'+n+'" alt=""><figcaption></figcaption></figure><p><strong>Step 3: Fill App Details</strong></p><ul><li>App Name: <code>Tradeboard</code></li><li>Redirect URL: <code>http://127.0.0.1:5000/pocketful/callback</code></li><li>Accept the terms and conditions and click <strong>Create App</strong></li></ul><figure><img src="'+s+'" alt=""><figcaption></figcaption></figure><p>Once created, the following credentials will be generated:</p><ul><li>App ID: use as <code>API_KEY</code></li><li>App Secret: use as <code>API_SECRET</code></li></ul><figure><img src="'+c+`" alt=""><figcaption></figcaption></figure><hr><h4 id="api-authentication" tabindex="-1">API Authentication <a class="header-anchor" href="#api-authentication" aria-label="Permalink to &quot;API Authentication&quot;">​</a></h4><p>Pocketful follows OAuth2-based authentication using redirect URI and access tokens. After app creation, Tradeboard uses the client credentials to initiate authorization and securely fetch access tokens.</p><p>Here is a sample of how the details would appear in a <code>.env</code> file for reference:</p><div class="language-env vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">env</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>BROKER_API_KEY = &#39;your_app_id_here&#39;</span></span>
<span class="line"><span>BROKER_API_SECRET = &#39;your_app_secret_here&#39;</span></span>
<span class="line"><span>REDIRECT_URL = &#39;http://127.0.0.1:5000/pocketful/callback&#39;</span></span></code></pre></div><hr><h4 id="connecting-pocketful-to-tradeboard" tabindex="-1">Connecting Pocketful to Tradeboard <a class="header-anchor" href="#connecting-pocketful-to-tradeboard" aria-label="Permalink to &quot;Connecting Pocketful to Tradeboard&quot;">​</a></h4><p>Once your <code>.env</code> file is populated with the credentials, restart Tradeboard, open the broker page and click <strong>Connect</strong>. Tradeboard builds the authorization URL from your credentials and sends you to <code>https://trade.pocketful.in/oauth2/auth</code>.</p><p>After you sign in, Pocketful redirects back to <code>http://127.0.0.1:5000/pocketful/callback</code> with an authorization code, which Tradeboard exchanges for an access token and stores locally. That completes the authentication process.</p><hr><p>Integrating Tradeboard with Pocketful&#39;s API allows traders and developers to leverage a powerful, cost-effective, and scalable infrastructure for building and deploying fully automated trading strategies. To ensure smooth performance, it is advisable to manage API limits, rotate tokens securely, and build retry/error-handling logic in production systems.</p><hr><h3 id="supported-exchanges" tabindex="-1">Supported Exchanges <a class="header-anchor" href="#supported-exchanges" aria-label="Permalink to &quot;Supported Exchanges&quot;">​</a></h3><p>Tradeboard reads this plugin&#39;s exchange list from <code>broker/pocketful/plugin.json</code> and serves it to the app, so symbol search, the Strategy Builder and the tools pages only offer what the plugin actually handles.</p><ul><li><strong>Tradable:</strong> <code>NSE</code>, <code>BSE</code>, <code>NFO</code>, <code>BFO</code>, <code>MCX</code></li><li><strong>Index feeds:</strong> <code>NSE_INDEX</code>, <code>BSE_INDEX</code></li></ul>`,35)])])}const m=t(l,[["render",p]]);export{b as __pageData,m as default};
